    'e-02-start': { transfers: ['Typed Jev answers + deterministic gate results'], boundary: 'Inside the Grok bot app.', artifacts: ['decision-record'] },
    'e-start-03': { transfers: ['Readiness: all gates passed', 'Selected model / runtime (eligible, capacity reserved)', 'Routing notes: owner, lane'], boundary: 'Inside the Grok bot app. None of this internal evidence is sent to the Superset host.', artifacts: ['decision-record'], rules: ['internal-evidence'] },
    'e-start-human': { transfers: ['`NEEDS_CLARIFICATION` reason code', 'Failed gate + source reference', 'Exact missing specification', 'Responsible owner'], notTransferred: ['Guessed or drafted replacement AC'], artifacts: ['decision-record'], rules: ['readiness-no-draft'] },
    'e-human-01': { transfers: ['Updated ticket (new revision)'], notTransferred: ['A chat reply instead of a ticket update', 'A direct answer to Jev'], rules: ['readiness-chat', 'human-no-direct-jev'] },
