  /* ── Glossary (tooltips) ────────────────────────────────────────────────────── */
  WF.glossary = {
    ac: { term: 'Acceptance Criteria (AC)', text: 'Observable conditions in the ticket that define WHAT must work. Only the human ticket owner writes them; agents never create or “improve” them.' },
    'verification-plan': { term: 'Verification Plan', text: 'HOW existing AC will be proven: strategy, test types, scenarios, boundary/negative cases, expected evidence. Scenarios challenge an AC; they are not new AC.' },
    proof: { term: 'PROOF', text: 'Independent review of the code AND of the tests’ ability to detect AC violations. Engineering evidence, not a mathematical proof.' },
    mutation: { term: 'Mutation testing', text: 'Deliberately changes the implementation (e.g. `< 480` → `< 600`) and checks that some test fails. A surviving mutant shows the tests are blind to that change.' },
    counterexample: { term: 'Counterexample', text: 'A concrete, allowed input or sequence under which the implementation violates an AC. For example: resize the container after unmount and the widget throws.' },
    verified: { term: 'VERIFIED', text: 'A planned scenario exists, evidence exists, the test observes the behavior the AC requires, a meaningful violation would make it fail, and no counterexample remains unexplained.' },
    failed: { term: 'FAILED', text: 'Evidence shows the implementation violates the AC (e.g. a reproduced counterexample).' },
    unverified: { term: 'UNVERIFIED', text: 'Not shown either way: a planned scenario is missing, a test is too weak, or verification could not run. Never recorded as a pass.' },
    'human-gate': { term: 'Human gate', text: 'A point where a named person must act: update the ticket, decide scope or risk, accept a build, or approve a release. Humans reply through the responsible WFTasks or WFRelease stage, never directly to Jev.' },
    promotion: { term: 'Promotion', text: 'Moving the candidate forward (e.g. staging merge, Ready for Release). It needs fresh evidence AND an explicit grant for that exact action.' },
    'needs-clarification': { term: 'NEEDS_CLARIFICATION', text: 'Readiness failed because the AC are missing, ambiguous, unverifiable, contradictory or lack context. The ticket returns to a human with the exact missing specification.' },
    jev: { term: 'Jev', text: 'TypeSafe Jev: answers narrow typed questions about text evidence (Noul / Choice). It cannot fetch issues, see images, run code or review changes.' },
    wftasks: { term: 'WFTasks', text: 'Grok bot for steps 01–07 and 15–17: reads the tracker (the tracker integration only), refreshes evidence, tracks waits and messages WFJev for every Jev decision.' },
    wfjev: { term: 'WFJev', text: 'Sole TypeSafe Jev front door of the PRJ-* Grok fleet. Other bots message it with evidence, the preset and a reply-to; it surfaces the questions in its own chat and returns a structured disposition.' },
    wfrelease: { term: 'WFRelease', text: 'Grok bot for steps 08–14: evidence refresh, waits, merges and delivery verification. It messages WFJev for the 09 and 13 decisions.' },
    wfreview: { term: 'WFReview', text: 'Grok bot that owns 06A and 06B only; it does not call Jev or message WFJev for those steps.' },
    wfcoder: { term: 'WFCoder', text: 'Grok fleet coding worker for take-to-work and rework: one Superset session started with the minimal launch payload.' },
    superset: { term: 'Superset', text: 'The implementation / review machine where worker sessions run. It only receives issue ID + operational notes + execution instructions.' },
    shadow: { term: 'Shadow mode', text: 'Policies record recommendations without acting. Both committed example policies are in shadow mode with every action grant disabled.' },
    'test-strength': { term: 'Test strength', text: 'Whether a test would fail if the implementation meaningfully violated the AC. `expect(component).toBeDefined()` has almost none for a layout AC.' },
    'green-ci': { term: 'Green CI', text: 'Mechanical evidence that checks ran and passed. It says nothing about whether the checks test the right behavior.' },
  };
